INSERT INTO learning_item_localizations (learning_item_localization_id, learning_item_version_id, locale, stem, explanation, status, source_locale, translation_method, translation_version, explanation_data, explanation_status, content_hash) VALUES ('item-localization-f05f0082c258bf4fe925', 'item-version-989b6a8375b4150ee322', 'zh-CN', '清除重复出现或无用的数据对于帮助分类器解决问题非常重要。', '本题考查“分类1”，参考答案为 A：“正确”。', 'needs_review', 'en', 'public_machine_translation', 'en-zh-candidate-2026-08-12', '{"correctOptionKey":"A","correctReason":"该陈述与课程中“分类1”的说明一致，因此应选择“正确”。","generationMethod":"machine_translation_plus_structural_template","generationVersion":"en-zh-candidate-2026-08-12","localizedStem":"清除重复出现或无用的数据对于帮助分类器解决问题非常重要。","memoryTip":"复习“分类1”时，先定位题干关键词，再逐项核对定义和适用条件。","optionReasons":{"A":"该陈述与课程中“分类1”的说明一致，因此应选择“正确”。","B":"“错误”不是本题参考答案；审核时需结合原课程补充它与正确选项的具体差异。"},"originalStem":"It''s important to clean out recurrent or unhelpful data to help your classifiers solve your problem.","quality":"structural_draft","requiresSubjectMatterReview":true,"schemaVersion":"quiz-explanation.v1","sourceUrls":["https://github.com/microsoft/ML-For-Beginners/blob/d0d0ea2b2d22cddca31f9c6d108df7daa87a1b46/quiz-app/src/assets/translations/en.json"],"summary":"本题考查“分类1”，参考答案为 A：“正确”。"}'::jsonb, 'needs_review', '490f691eb74315c0003733ad0bfc1819419e52f49e796d2abe2c641e24178dba') ON CONFLICT (learning_item_version_id, locale) DO NOTHING;
